from typing import List

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    parts = []
    for degree, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        current_degree = n - degree

        # Determine the sign
        if parts:
            sign = "+" if coeff > 0 else "-"
        else:
            sign = "-" if coeff < 0 else ""

        abs_coeff = abs(coeff)

        # Determine the coefficient part
        if current_degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = str(abs_coeff) if abs(coeff) != 1 else ""

        # Determine the variable part
        if current_degree == 0:
            var_str = ""
        elif current_degree == 1:
            var_str = "x"
        else:
            var_str = f"x^{current_degree}"

        term = sign + coeff_str + var_str
        if term:  # only add non-empty terms (shouldn't be empty if coeff != 0)
            parts.append(term)

    if not parts:
        return "0"

    return "".join(parts)
