def decode(encoded: str, original: str, message: str) -> str:
    # Step 1: Basic validation
    if len(encoded) != len(original):
        return "Failed"

    # Step 2: Build mapping from encoded letters to original letters
    mapping = {}

    for enc_char, orig_char in zip(encoded, original):
        # If we've already mapped this encoded character to a different original character, there's a contradiction
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            # Check if this original character is already mapped from a different encoded character
            # This would be a contradiction because the cipher must be one-to-one (bijection)
            for enc_key, orig_val in mapping.items():
                if orig_val == orig_char and enc_key != enc_char:
                    return "Failed"
            mapping[enc_char] = orig_char

    # Step 3: Check if all letters in the message are covered by the mapping
    for char in message:
        if char not in mapping:
            return "Failed"

    # Step 4: Decode the message
    decoded = ""
    for char in message:
        decoded += mapping[char]

    return decoded

