def count_coprime_pairs(x0: int, y0: int) -> int:
    if x0 == 0 or y0 % x0 != 0:
        return 0

    n = y0 // x0
    count = 0

    for a in range(1, int(n**0.5) + 1):
        if n % a == 0:
            b = n // a
            # Check if a and b are coprime
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a
