def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    def is_day_of_week(statement: str) -> bool:
        # A statement about the day of the week if any word in the statement is a day of the week (case-insensitive)
        words = statement.upper().split()
        return any(word in days_of_week for word in words)

    def evaluate_statement(statement: str, speaker: str, scenario: str) -> bool:
        """
        Evaluate whether a single statement is true given the scenario (who is guilty).
        """
        statement_upper = statement.upper().strip()
        scenario_upper = scenario.upper()
        speaker_upper = speaker.upper()

        # First, ignore statements about days of the week
        if is_day_of_week(statement):
            return True  # Disregard statements about days of the week

        # Normalize the statement for evaluation
        # Handle "I am guilty"
        if statement_upper in ["I AM GUILTY", "I AM THE CULPRIT", "I DID IT"]:
            return speaker_upper == scenario_upper

        # Handle "I am not guilty"
        if statement_upper in ["I AM NOT GUILTY", "I AM NOT THE CULPRIT", "I DID NOT DO IT"]:
            return speaker_upper != scenario_upper

        # Handle "X is guilty" or "X is the culprit"
        for name in statements:
            name_upper = name.upper()
            if name_upper != speaker_upper:
                guilty_phrases = [
                    f"{name_upper} IS GUILTY",
                    f"{name_upper} IS THE CULPRIT",
                    f"{name_upper} DID IT"
                ]
                if statement_upper in guilty_phrases:
                    return name_upper == scenario_upper

        # Handle "X is not guilty"
        for name in statements:
            name_upper = name.upper()
            if name_upper != speaker_upper:
                not_guilty_phrases = [
                    f"{name_upper} IS NOT GUILTY",
                    f"{name_upper} IS NOT THE CULPRIT",
                    f"{name_upper} DID NOT DO IT",
                    f"{name_UPPER} IS INNOCENT"
                ]
                if statement_upper in not_guilty_phrases:
                    return name_upper != scenario_upper

        # Handle "I am innocent" (already covered by "I am not guilty")

        # If the statement doesn't match any known pattern, assume it's consistent (True)
        # This is a fallback to avoid failing on unrecognized but non-contradictory statements
        return True

    # Check if the scenario is consistent with the set of liars
    for speaker, speaker_statements in statements.items():
        is_liar = speaker in liar_count

        for statement in speaker_statements:
            # Evaluate if the statement is true or false given the scenario
            statement_is_true = evaluate_statement(statement, speaker, scenario)

            # If the speaker is a liar, the statement MUST be false
            # If the speaker is not a liar (truth-teller), the statement MUST be true
            if is_liar:
                if statement_is_true:
                    return False
            else:
                if not statement_is_true:
                    return False

    return True

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # dp[j] will be True if a sum of j is possible using some subset of volumes
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes:
        # Traverse from V down to vol to avoid using the same item multiple times
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True

    # Find the maximum sum that is achievable and <= V
    max_occupied = 0
    for j in range(V, -1, -1):
        if dp[j]:
            max_occupied = j
            break

    return V - max_occupied

