def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    # T(n) = 2 * T(n-1) + 2
    # T(1) = 2
    moves = 2  # T(1)
    if n <= 1:
        return moves
    for i in range(2, n + 1):
        moves = 2 * moves + 2
    return moves
